      "path": "dsh-plugin-desktop/src/host-bootstrap.ts",
      "content": "/** Headless bootstrap for the Beta isolated Host experiment. */\nimport { boot, resolveProfileDir } from '@deepseek-ai/dsh-app-boot'\nimport { provideCmdline } from '@deepseek-ai/dsh-cmdline'\nimport { createDesktopProfileBoot } from './profile-context.ts'\nimport { logInactiveStartupEntries } from './startup-audit.ts'\nimport { DSH_LAUNCH_ENVIRONMENT_KEY, type LaunchEnvironmentSnapshot } from '@deepseek-ai/dsh-launch-environment'\nimport { DESKTOP_PACKAGE_NAME as BIN_NAME } from './product-identity.ts'\nimport { observeDesktopPreferenceSettings } from './settings-bridge.ts'\nimport { installProfilePackageResolver } from './module-resolution.ts'\nimport { DesktopPluginPackages } from './plugin-packages.ts'\nimport { createDesktopWebProfile, listDesktopProfiles, canDeleteDesktopProfile, deleteDesktopProfile, selectDesktopProfile } from './profile-manager.ts'\nimport { DesktopProfileService } from './profile-service.ts'\nimport { DesktopActionsService } from './desktop-actions.ts'\nimport { clearDesktopProfilePluginState, DesktopPluginsService } from './desktop-plugins.ts'\nimport { desktopMarketSnapshotWithEffective, selectDesktopMarketProvider, type DesktopMarketProvider, type DesktopMarketSnapshot } from './desktop-market.ts'\nimport DesktopSettingsController from './desktop-settings-controller.ts'\nimport { clearDesktopProfilePreferences, desktopProfilePreferencesFromSettings, readDesktopProfilePreferences, writeDesktopProfilePreferences, type DesktopProfilePreferences, type DesktopProfilePreferencesStateV1 } from './profile-preferences.ts'\nimport { clearDesktopProfileUsageHistory, type DesktopReleaseUserDataLocations } from './profile-channel-admission.ts'\nimport { desktopInstallAnchor, type PreparedDesktopProfile } from './profile.ts'\nimport { desktopLanBrowserUrls, desktopLoopbackBrowserUrl } from './desktop-network.ts'\nimport { DESKTOP_LAN_HTTPS_CA_PATH, type DesktopLanHttpsRuntime } from './lan-https-runtime.ts'\nimport type { DesktopBrowserAccess } from './desktop-browser-access.ts'\nimport type { DesktopPnpmBootstrap } from './pnpm.ts'\nimport type { DesktopRuntime } from './runtime.ts'\nimport type { DesktopStartupGenerationHost } from './startup-generation.ts'\nimport { FileExporter } from './file-exporter.ts'\nimport { initializeDeveloperLogging, diagnosticRunId } from './developer-logging.ts'\nimport { installHostDeveloperLogging } from './host-developer-logging.ts'\nimport { installAgentErrorLogging } from './agent-error-logging.ts'\nimport { LogFileSink } from './log-files.ts'\nimport * as desktopOffice from './desktop-office.ts'\nimport { resolveDesktopOfficeConfig, type DesktopPrimaryRuntime } from './desktop-office.ts'\n\nfunction desktopProfileMarketSnapshot(market: DesktopMarketProvider): DesktopMarketSnapshot {\n  return Object.freeze({\n    requested: market,\n    effective: market,\n    legacyDefaulted: false,\n  })\n}\n\nexport interface DesktopHostOptions {\n  prepared: PreparedDesktopProfile\n  profilePreferences: DesktopProfilePreferences\n  homeDir: string\n  activeProfileName: string\n  pluginManagementStatePath: string\n  selectionStatePath: string\n  marketUserDataDir: string\n  releaseUserDataLocations: DesktopReleaseUserDataLocations\n  desktopLaunchEnvironment: LaunchEnvironmentSnapshot\n  /**\n   * Proxy names the supervisor synthesized from the operating system's configuration, keyed\n   * lowercase, empty when the user exported a proxy themselves or the machine has none.\n   *\n   * Passed rather than re-derived: a launch environment snapshot is frozen when it loads, so the\n   * supervisor's later writes to `process.env` never reach it, and the Host re-probing on its own\n   * could reach a different answer than the window the user is looking at.\n   */\n  desktopProxyOverlay: Readonly<Record<string, string>>\n  desktopPnpmBootstrap: DesktopPnpmBootstrap\n  /** Bundled interpreter payload of this CPU; a packaged Host fails without it, a development Host skips Office until `prepare:runtime` ran. */\n  primaryRuntime?: DesktopPrimaryRuntime\n  logDirectory: string\n  diagnosticRunId?: string\n}\n\nexport async function bootDesktopHost(options: DesktopHostOptions, runtime: DesktopRuntime,\n  browserAccess: DesktopBrowserAccess, lanHttps: DesktopLanHttpsRuntime,\n  bindHost: (host: DesktopStartupGenerationHost) => void, requestQuit: (code: number) => void,\n): Promise<() => { aaRuntime: boolean; aaOnboarding: boolean }> {\n  const { prepared, profilePreferences, homeDir, activeProfileName, pluginManagementStatePath,\n    selectionStatePath, marketUserDataDir, releaseUserDataLocations, desktopLaunchEnvironment,\n    desktopPnpmBootstrap } = options\n  const createFreshDesktopProfile = (name: string) => {\n    const created = createDesktopWebProfile(homeDir, name)\n    clearDesktopProfileUsageHistory(releaseUserDataLocations, created.dir)\n    return created\n  }\n  const logSink = new LogFileSink(options.logDirectory, {\n    maxFileBytes: 10 * 1024 * 1024, maxDirectoryBytes: 200 * 1024 * 1024,\n  })\n  logSink.purgeOlderThan(7)\n  initializeDeveloperLogging((level, line) => logSink.writeRecord(level, JSON.parse(line)), options.diagnosticRunId ?? diagnosticRunId())\n  let fileExporter: FileExporter | undefined\n    let currentProfilePreferences: DesktopProfilePreferences = profilePreferences\n    let profilePreferencesWriteTail: Promise<void> = Promise.resolve()\n    let profilePreferencesStopping = false\n    // Setup saves from the Electron process after this Host booted; follow the\n    // durable file so its Market and AA choices are neither reverted nor hidden.\n    const latestProfilePreferences = (): DesktopProfilePreferences =>\n      readDesktopProfilePreferences(marketUserDataDir, prepared.profile.dir) ?? currentProfilePreferences\n    const readProfilePreferences = (): DesktopProfilePreferences => {\n      try { return latestProfilePreferences() } catch { return currentProfilePreferences }\n    }\n    const enqueueProfilePreferencesWrite = (\n      update: (current: DesktopProfilePreferences) => DesktopProfilePreferences,\n    ): Promise<DesktopProfilePreferencesStateV1> => {\n      if (profilePreferencesStopping) {\n        return Promise.reject(new Error(`${BIN_NAME}: Profile preferences are stopping`))\n      }\n      const write = profilePreferencesWriteTail.then(async () => {\n        const next = update(latestProfilePreferences())\n        const stored = await writeDesktopProfilePreferences(\n          marketUserDataDir,\n          prepared.profile.dir,\n          next,\n        )\n        currentProfilePreferences = stored\n        return stored\n      })\n      profilePreferencesWriteTail = write.then(() => undefined, () => undefined)\n      return write\n    }\n    const flushProfilePreferencesWrites = async (): Promise<void> => {\n      profilePreferencesStopping = true\n      await profilePreferencesWriteTail\n    }\n    let effectiveMarket = prepared.market.effective\n    let effectiveAa = prepared.aaEnabled\n    const releasePackageResolver = installProfilePackageResolver(prepared.bareModuleBaseUrl)\n    const profileBoot = createDesktopProfileBoot(prepared, desktopPnpmBootstrap, {\n      onManagedBundlesChanged: state => {\n        effectiveMarket = state.effectiveMarket\n        effectiveAa = state.effectiveAa\n        void enqueueProfilePreferencesWrite(current => desktopProfilePreferencesFromSettings(\n          current,\n          current.notifications,\n          state.requestedMarket,\n          state.requestedAa,\n        )).then(() => selectDesktopMarketProvider(marketUserDataDir, state.requestedMarket))\n          .catch(() => {})\n      },\n    })\n    const ctx = await boot(\n      BIN_NAME,\n      prepared.rootConfig,\n      prepared.patches,\n      async (hostCtx) => {\n        profileBoot.prepare(hostCtx)\n        // Keep Host imports and browser bundle discovery on the same public\n        // profile-overlay resolver used by packaged Electron.\n        hostCtx.loader.internal = undefined\n        bindHost(hostCtx)\n        hostCtx.effect(() => () => logSink.close(), 'dsh-plugin-desktop: Host log sink')\n        hostCtx.effect(\n          () => async () => { await flushProfilePreferencesWrites() },\n          'dsh-plugin-desktop: flush Profile preference writes',\n        )\n        hostCtx.effect(\n          () => releasePackageResolver,\n          'dsh-plugin-desktop: profile package resolution',\n        )\n        // Official plugin metadata and package lookups read the packages this resolver loads.\n        await hostCtx.plugin(DesktopPluginPackages)\n        hostCtx.provide(DSH_LAUNCH_ENVIRONMENT_KEY, desktopLaunchEnvironment)\n        hostCtx.provide('desktopBrowserAccess', browserAccess)\n        hostCtx.provide('desktopLanHttps', lanHttps)\n        hostCtx.provide('desktopRuntime', runtime)\n        hostCtx.provide('desktopPnpmBootstrap', desktopPnpmBootstrap)\n        await hostCtx.plugin(DesktopActionsService, {\n          openTerminal: () => { runtime.openTerminal() },\n          requestRestart: () => runtime.requestRestart(),\n        })\n        await hostCtx.plugin(DesktopPluginsService, {\n          profileName: activeProfileName,\n          homeDir,\n          statePath: pluginManagementStatePath,\n          installAnchor: desktopInstallAnchor(),\n        })\n        if (logSink !== undefined) {\n          fileExporter = new FileExporter(logSink)\n          hostCtx.logger.exporter(fileExporter)\n        }\n        // Registered before the plugin tree mounts, so no agent can fail unrecorded.\n        installAgentErrorLogging(hostCtx)\n        installHostDeveloperLogging(hostCtx)\n        // Office skills and the workspace dependency tool need the bundled payload; a packaged Host without it fails here.\n        const office = resolveDesktopOfficeConfig(options.primaryRuntime, homeDir)\n        if (office === undefined) {\n          hostCtx.logger.warn(`${BIN_NAME}: Office skills are unavailable; run yarn prepare:runtime to prepare the primary runtime`)\n        } else {\n          await hostCtx.plugin(desktopOffice, office)\n          hostCtx.logger.info(`${BIN_NAME}: Office skills mounted from ${office.source}`)\n        }\n        await hostCtx.plugin(DesktopProfileService, {\n          current: {\n            name: activeProfileName,\n            dir: prepared.profile.dir,\n          },\n          create: name => createFreshDesktopProfile(name),\n          list: () => listDesktopProfiles(homeDir),\n          canDelete: name => canDeleteDesktopProfile({\n            home: homeDir,\n            selectionStatePath,\n            currentProfileName: activeProfileName,\n          }, name),\n          delete: async name => {\n            const profileDir = resolveProfileDir(name, homeDir)\n            await deleteDesktopProfile({\n              home: homeDir,\n              selectionStatePath,\n              currentProfileName: activeProfileName,\n              clearDisabledState: () => clearDesktopProfilePluginState(pluginManagementStatePath, name),\n              clearCheckpoint: async () => {\n                clearDesktopProfileUsageHistory(releaseUserDataLocations, profileDir)\n              },\n            }, name)\n            try {\n              await clearDesktopProfilePreferences(marketUserDataDir, profileDir)\n            } catch (cause) {\n              hostCtx.logger.error(\n                `${BIN_NAME}: deleted Profile left stale preference state: ${cause instanceof Error ? cause.message : String(cause)}`,\n              )\n            }\n          },\n          persistSelection: name => { selectDesktopProfile(selectionStatePath, homeDir, name) },\n          requestRestart: () => runtime.requestRestart(),\n        })\n        let pendingSettingsRestart: ReturnType<typeof setImmediate> | undefined\n        const scheduleSettingsRestart = (): void => {\n          pendingSettingsRestart ??= setImmediate(() => {\n            pendingSettingsRestart = undefined\n            void runtime.requestRestart().catch((cause: unknown) => {\n              hostCtx.logger.error(\n                `${BIN_NAME}: failed to restart after Desktop setting change: ${cause instanceof Error ? cause.message : String(cause)}`,\n              )\n            })\n          })\n        }\n        hostCtx.effect(() => () => {\n          if (pendingSettingsRestart !== undefined) clearImmediate(pendingSettingsRestart)\n          pendingSettingsRestart = undefined\n        }, 'dsh-plugin-desktop: pending Desktop settings restart')\n        const readMarket = () => desktopMarketSnapshotWithEffective(\n          desktopProfileMarketSnapshot(readProfilePreferences().market),\n          effectiveMarket,\n        )\n        hostCtx.provide('desktopSettingsController', new DesktopSettingsController({\n          profiles: hostCtx.desktopProfiles,\n          readMarket,\n          readAa: () => ({ requested: readProfilePreferences().aaEnabled === true, effective: effectiveAa }),\n          selectAa: async enabled => {\n            await enqueueProfilePreferencesWrite(current => desktopProfilePreferencesFromSettings(\n              current,\n              current.notifications,\n              current.market,\n              enabled,\n            ))\n          },\n          readWeb: () => {\n            const port = hostCtx.webServer.port\n            if (port === undefined) {\n              throw new Error('dsh-plugin-desktop: the WebServer has not bound a port')\n            }\n            const lan = lanHttps.snapshot()\n            const lanOrigins = lan.state === 'ready' && lan.actualPort !== null\n              ? desktopLanBrowserUrls(lan.actualPort, lan.addresses)\n              : []\n            return {\n              localUrl: hostCtx.connection.authenticatedUrl(\n                desktopLoopbackBrowserUrl(port),\n              ),\n              lanUrls: lanOrigins.map(url => hostCtx.connection.authenticatedUrl(url)),\n              lanState: lan.state,\n              lanError: lan.errorCode,\n              lanCaFingerprint: lan.caFingerprint,\n              lanCaUrls: lanOrigins.map((origin) => {\n                return new URL(DESKTOP_LAN_HTTPS_CA_PATH, origin).href\n              }),\n            }\n          },\n          selectMarket: async provider => {\n            await enqueueProfilePreferencesWrite(current => desktopProfilePreferencesFromSettings(\n              current,\n              current.notifications,\n              provider,\n              current.aaEnabled === true,\n            ))\n            return desktopMarketSnapshotWithEffective(\n              await selectDesktopMarketProvider(marketUserDataDir, provider),\n              effectiveMarket,\n            )\n          },\n          scheduleRestart: scheduleSettingsRestart,\n          scheduleRecoveryRestart: () => {\n            void runtime.requestRecoveryRestart().catch((cause: unknown) => {\n              hostCtx.logger.error(\n                `${BIN_NAME}: failed to restart in recovery mode: ${cause instanceof Error ? cause.message : String(cause)}`,\n              )\n            })\n          },\n          openTerminal: () => { runtime.openTerminal() },\n          reloadRenderer: () => { runtime.reloadRenderer() },\n          toggleDeveloperTools: () => { runtime.toggleDeveloperTools() },\n          exportDiagnostics: () => runtime.exportDiagnostics(),\n        }))\n        provideCmdline(hostCtx, {\n          args: [\n            '--port',\n            String(prepared.port),\n          ],\n          exit: requestQuit,\n        })\n      },\n      prepared.bareModuleBaseUrl,\n    ).catch((cause: unknown) => {\n      releasePackageResolver()\n      throw cause\n    })\n    bindHost(ctx)\n    profileBoot.markReady()\n    observeDesktopPreferenceSettings(ctx, fileExporter, enqueueProfilePreferencesWrite)\n    void logInactiveStartupEntries(ctx, BIN_NAME)\n  return () => ({ aaRuntime: ctx.get('agentsAnywhereRuntime') !== undefined, aaOnboarding: ctx.get('agentsAnywhereOnboarding') !== undefined })\n}\n"
    },
    {
      "path": "dsh-plugin-desktop/src/index.ts",
      "content": "/** DSH Desktop Host plugin: owns the selected native shell generation. */\n\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { fileURLToPath } from 'node:url'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-cmdline'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type {} from '@deepseek-ai/dsh-client-connection'\nimport {\n  handleRendererBootRequest,\n  RENDERER_BOOT_REPORT_PATH,\n} from './renderer-boot.ts'\nimport {\n  DESKTOP_DIRECTORY_PICKER_PATH,\n  DESKTOP_DIRECTORY_VALIDATOR_PATH,\n} from './directory-picker-contract.ts'\nimport {\n  handleDesktopDirectoryPickerRequest,\n  handleDesktopDirectoryValidationRequest,\n} from './directory-picker-route.ts'\nimport {\n  DESKTOP_DIAGNOSTICS_EXPORT_PATH,\n  DESKTOP_DEVELOPER_TOOLS_TOGGLE_PATH,\n  DESKTOP_AA_SELECT_PATH,\n  DESKTOP_MARKET_SELECT_PATH,\n  DESKTOP_PROFILE_CREATE_PATH,\n  DESKTOP_PROFILE_DELETE_PATH,\n  DESKTOP_PROFILE_SELECT_PATH,\n  DESKTOP_RESTART_PATH,\n  DESKTOP_RECOVERY_RESTART_PATH,\n  DESKTOP_RENDERER_RELOAD_PATH,\n  DESKTOP_SETTINGS_PATH,\n  DESKTOP_TERMINAL_OPEN_PATH,\n} from './desktop-settings-contract.ts'\nimport {\n  handleDesktopDiagnosticsExportRequest,\n  handleDesktopDeveloperToolsToggleRequest,\n  handleDesktopAaSelectRequest,\n  handleDesktopMarketSelectRequest,\n  handleDesktopProfileCreateRequest,\n  handleDesktopProfileDeleteRequest,\n  handleDesktopProfileSelectRequest,\n  handleDesktopRestartRequest,\n  handleDesktopRecoveryRestartRequest,\n  handleDesktopRendererReloadRequest,\n  handleDesktopSettingsRequest,\n  handleDesktopTerminalOpenRequest,\n} from './desktop-settings-route.ts'\nimport type {} from './desktop-settings-controller.ts'\nimport { DESKTOP_LAN_HTTPS_CA_PATH } from './lan-https-runtime.ts'\nimport { desktopBootRecoveryInjections } from './desktop-boot-recovery.ts'\nimport type { DesktopLocale, DesktopShellMode } from './runtime.ts'\nimport type {} from './runtime.ts'\nimport {\n  desktopBrowserAccessEnabled,\n  desktopNetworkExposureForBrowserAccess,\n  desktopWebServerHost,\n  type DesktopNetworkExposure,\n} from './desktop-network.ts'\nimport { DESKTOP_FRAME_HEIGHT } from './window-chrome.ts'\nimport {\n  effectiveDesktopWindowMaterial,\n  type DesktopWindowMaterial,\n} from './window-material.ts'\nimport { DESKTOP_PRODUCT_NAME } from './product-identity.ts'\nimport { watchPlatformLogin, type PlatformLoginAccount } from './platform-login.ts'\nimport type { DesktopSetupWizardSettings } from './setup-wizard-settings.ts'\nimport {\n  createDesktopSettingsPort,\n  DESKTOP_NOTIFICATIONS_SETTINGS_ENTRY_ID,\n  readUiLocalePreference,\n  readUiThemeSource,\n  resolveDesktopConfig,\n  watchUiLocalePreference,\n  watchUiThemeSource,\n  type DesktopShellConfig,\n} from './settings-bridge.ts'\n\n/** Stable Cordis plugin name. */\nexport const name = 'desktop-shell'\n\n/** Services required before the shell can register its renderer generation. */\n/** Services required by the desktop shell; `desktopRuntime` is probed, not required. */\nexport const inject = ['webServer', 'appExit', 'settings', 'connection']\n\n/**\n * Standard settings namespace shared by tray and configuration surfaces, the\n * editable preference subset, and the validated native window configuration.\n * All three are edition-local because the two channels' cores model plugin\n * configuration differently; see `src/settings-bridge.ts`.\n */\nexport {\n  DESKTOP_SETTINGS_NAMESPACE,\n  DesktopSettingsSchema,\n  DesktopShellConfig as Config,\n  type DesktopSettings,\n} from './settings-bridge.ts'\n\n/** Apply the official Connection trust and browser-auth fence before a private Desktop route. */\nfunction rejectDesktopRequest(\n  ctx: Context,\n  req: IncomingMessage,\n  res: ServerResponse,\n): boolean {\n  const rejection = ctx.connection.requestRejection(req)\n  if (rejection === undefined) return false\n  res.writeHead(rejection)\n  res.end(rejection === 401 ? 'unauthorized' : 'forbidden')\n  return true\n}\n\n/** Narrow the upstream locale preference to the translations bundled by Desktop chrome. */\nfunction desktopLocalePreference(preference: string | undefined): DesktopLocale | undefined {\n  return preference === 'zh' || preference === 'en' ? preference : undefined\n}\n\n/**\n * Construct the unmodified upstream Web root URL.\n * @param port - active loopback Web server port.\n * @param mode - active native presentation mode.\n * @param platform - active Electron platform.\n * @returns the URL loaded by the BrowserWindow.\n */\nexport function desktopRendererUrl(\n  port: number,\n  mode: DesktopShellMode,\n  platform: Context['desktopRuntime']['platform'],\n  appVersion: string,\n  material: DesktopWindowMaterial = 'off',\n): string {\n  const url = new URL(`http://127.0.0.1:${String(port)}/`)\n  url.searchParams.set('dsh-desktop-mode', mode)\n  url.searchParams.set('dsh-desktop-platform', platform)\n  url.searchParams.set('dsh-desktop-version', appVersion)\n  url.searchParams.set('dsh-desktop-material', material)\n  if (mode === 'extended' || (mode === 'compatibility' && platform !== 'linux')) {\n    // Body-level plugin portals do not inherit the framed root's geometry.\n    // Publish the exact content boundary so they can yield Desktop chrome.\n    url.searchParams.set('dsh-desktop-titlebar-inset', String(DESKTOP_FRAME_HEIGHT))\n  }\n  return url.href\n}\n\n/**\n * Register the Electron shell from active Web carrier values.\n * @param ctx - Host context carrying the Electron adapter and Web carrier.\n * @param config - validated native window values.\n */\nexport function apply(ctx: Context, config: DesktopShellConfig): void {\n  const runtime = ctx.get('desktopRuntime')\n  if (runtime === undefined) {\n    process.stderr.write(\n      'dsh-plugin-desktop: this profile is composed with the DSH Desktop shell, which requires the desktop launcher (desktopRuntime).\\n'\n      + 'Start it with `dsh-desktop`, or select this profile inside the packaged DSH Desktop application.\\n'\n      + 'The desktop terminal, profile, and update rows stay inactive in an ordinary DSH boot.\\n',\n    )\n    return\n  }\n  const appExit = ctx.get('appExit')\n  if (appExit === undefined) {\n    throw new Error('dsh-plugin-desktop: the launcher did not provide ctx.appExit')\n  }\n  const browserAccess = ctx.get('desktopBrowserAccess')\n  if (browserAccess === undefined) {\n    throw new Error('dsh-plugin-desktop: the launcher did not provide ctx.desktopBrowserAccess')\n  }\n  const lanHttps = ctx.get('desktopLanHttps')\n  if (lanHttps === undefined) {\n    throw new Error('dsh-plugin-desktop: the launcher did not provide ctx.desktopLanHttps')\n  }\n  const resolved = resolveDesktopConfig(config)\n  if (ctx.webServer.host !== desktopWebServerHost(resolved.networkExposure)) {\n    throw new Error('dsh-plugin-desktop: desktop shell WebServer host does not match networkExposure')\n  }\n  const webServerPort = ctx.webServer.port\n  if (webServerPort === undefined) {\n    throw new Error('dsh-plugin-desktop: the WebServer has not bound a port')\n  }\n  lanHttps.attach(webServerPort)\n  const iconFilename = runtime.platform === 'darwin'\n    ? 'app-icon-mac.png'\n    : 'app-icon.png'\n  const iconPath = fileURLToPath(new URL(`../build/${iconFilename}`, import.meta.url))\n  const trayIcons = {\n    templatePath: fileURLToPath(new URL('../build/tray-iconTemplate.png', import.meta.url)),\n    bluePath: fileURLToPath(new URL('../build/tray-icon-blue.png', import.meta.url)),\n  }\n  const settings = createDesktopSettingsPort(ctx, config, runtime.platform)\n  // Choices first-run Setup saved into this generation's settings. Setup's own\n  // continuation offers the restart that applies them, after its account step.\n  let setupSettings: DesktopSetupWizardSettings | undefined\n  let setupSaved = false\n  const rendererOrigin = `http://127.0.0.1:${String(webServerPort)}`\n  ctx.effect(\n    () => ctx.webServer.register({\n      kind: 'exact',\n      path: DESKTOP_LAN_HTTPS_CA_PATH,\n      handler: (req, res) => {\n        if (req.method !== 'GET' && req.method !== 'HEAD') {\n          res.statusCode = 405\n          res.setHeader('allow', 'GET, HEAD')\n          res.setHeader('cache-control', 'no-store')\n          res.end('method not allowed')\n          return\n        }\n        const caCertificate = lanHttps.caCertificate\n        if (caCertificate === null) {\n          res.statusCode = 503\n          res.setHeader('cache-control', 'no-store')\n          res.end(req.method === 'HEAD' ? undefined : 'LAN HTTPS certificate unavailable')\n          return\n        }\n        res.statusCode = 200\n        res.setHeader('cache-control', 'no-store')\n        res.setHeader('content-type', 'application/x-x509-ca-cert')\n        res.setHeader('content-disposition', 'attachment; filename=\"dsh-desktop-local-ca.crt\"')\n        res.setHeader('content-length', String(Buffer.byteLength(caCertificate)))\n        res.setHeader('x-content-type-options', 'nosniff')\n        res.end(req.method === 'HEAD' ? undefined : caCertificate)\n      },\n    }),\n    'dsh-plugin-desktop: public LAN HTTPS CA route',\n  )\n  ctx.on('webserver/index-inject', table => {\n    table.push(...desktopBootRecoveryInjections())\n  })\n  const desktopSettings = ctx.get('desktopSettingsController')\n  if (desktopSettings !== undefined) {\n    const reportSettingsError = (operation: string, cause: unknown): void => {\n      ctx.logger.error(\n        `dsh-plugin-desktop: failed to ${operation}: ${cause instanceof Error ? cause.message : String(cause)}`,\n      )\n    }\n    const settingsRoutes = [\n      [DESKTOP_SETTINGS_PATH, handleDesktopSettingsRequest],\n      [DESKTOP_PROFILE_CREATE_PATH, handleDesktopProfileCreateRequest],\n      [DESKTOP_PROFILE_DELETE_PATH, handleDesktopProfileDeleteRequest],\n      [DESKTOP_PROFILE_SELECT_PATH, handleDesktopProfileSelectRequest],\n      [DESKTOP_AA_SELECT_PATH, handleDesktopAaSelectRequest],\n      [DESKTOP_MARKET_SELECT_PATH, handleDesktopMarketSelectRequest],\n      [DESKTOP_TERMINAL_OPEN_PATH, handleDesktopTerminalOpenRequest],\n      [DESKTOP_RESTART_PATH, handleDesktopRestartRequest],\n      [DESKTOP_RECOVERY_RESTART_PATH, handleDesktopRecoveryRestartRequest],\n      [DESKTOP_RENDERER_RELOAD_PATH, handleDesktopRendererReloadRequest],\n      [DESKTOP_DEVELOPER_TOOLS_TOGGLE_PATH, handleDesktopDeveloperToolsToggleRequest],\n      [DESKTOP_DIAGNOSTICS_EXPORT_PATH, handleDesktopDiagnosticsExportRequest],\n    ] as const\n    for (const [path, handler] of settingsRoutes) {\n      ctx.effect(\n        () => ctx.webServer.register({\n          kind: 'exact',\n          path,\n          handler: (req, res) => {\n            if (rejectDesktopRequest(ctx, req, res)) return\n            return handler(\n              req,\n              res,\n              rendererOrigin,\n              desktopSettings,\n              reportSettingsError,\n            )\n          },\n        }),\n        `dsh-plugin-desktop: private settings route ${path}`,\n      )\n    }\n  }\n  ctx.effect(\n    () => ctx.webServer.register({\n      kind: 'exact',\n      path: RENDERER_BOOT_REPORT_PATH,\n      handler: (req, res) => {\n        if (rejectDesktopRequest(ctx, req, res)) return\n        return handleRendererBootRequest(\n          req,\n          res,\n          rendererOrigin,\n          report => { runtime.reportRendererBoot(report) },\n        )\n      },\n    }),\n    'dsh-plugin-desktop: renderer boot report route',\n  )\n  if (runtime.platform === 'win32') {\n    ctx.effect(\n      () => ctx.webServer.register({\n        kind: 'exact',\n        path: DESKTOP_DIRECTORY_PICKER_PATH,\n        handler: (req, res) => {\n          if (rejectDesktopRequest(ctx, req, res)) return\n          return handleDesktopDirectoryPickerRequest(\n            req,\n            res,\n            rendererOrigin,\n            () => runtime.pickDirectory(),\n            cause => {\n              ctx.logger.error(`dsh-plugin-desktop: native directory picker failed: ${cause instanceof Error ? cause.message : String(cause)}`)\n            },\n          )\n        },\n      }),\n      'dsh-plugin-desktop: native directory picker route',\n    )\n    ctx.effect(\n      () => ctx.webServer.register({\n        kind: 'exact',\n        path: DESKTOP_DIRECTORY_VALIDATOR_PATH,\n        handler: (req, res) => {\n          if (rejectDesktopRequest(ctx, req, res)) return\n          return handleDesktopDirectoryValidationRequest(\n            req,\n            res,\n            rendererOrigin,\n            path => runtime.validateDirectory(path),\n            cause => {\n              ctx.logger.error(`dsh-plugin-desktop: workspace directory validation failed: ${cause instanceof Error ? cause.message : String(cause)}`)\n            },\n          )\n        },\n      }),\n      'dsh-plugin-desktop: workspace directory validation route',\n    )\n  }\n  ctx.effect(() => {\n    let pending: ReturnType<typeof setImmediate> | undefined\n    const updateLiveWebAccess = (\n      browserEnabled: boolean,\n      exposure: DesktopNetworkExposure,\n    ): void => {\n      browserAccess.setOrdinaryBrowserEnabled(browserEnabled)\n      void lanHttps.setEnabled(browserEnabled && exposure === 'lan').then((snapshot) => {\n        if (snapshot.state === 'failed') {\n          ctx.logger.error(\n            `dsh-plugin-desktop: LAN HTTPS edge failed to start (${snapshot.errorCode ?? 'unknown'})`,\n          )\n        }\n      }).catch((cause: unknown) => {\n        ctx.logger.error(\n          `dsh-plugin-desktop: LAN HTTPS edge transition failed: ${cause instanceof Error ? cause.message : String(cause)}`,\n        )\n      })\n    }\n    updateLiveWebAccess(browserAccess.ordinaryBrowserEnabled, resolved.networkExposure)\n    const stopWatching = settings.watch((next) => {\n      const nextBrowserAccess = desktopBrowserAccessEnabled(\n        next.mode,\n        next.openBrowser,\n        next.networkExposure,\n      )\n      const nextNetworkExposure = desktopNetworkExposureForBrowserAccess(\n        nextBrowserAccess,\n        next.networkExposure,\n      )\n      updateLiveWebAccess(nextBrowserAccess, nextNetworkExposure)\n      const matchesSetup = setupSettings !== undefined\n        && next.mode === setupSettings.mode\n        && next.port === resolved.port\n        && next.macosMaterial === setupSettings.macosMaterial\n        && next.linuxMaterial === resolved.linuxMaterial\n      // Once saved, any other value supersedes Setup's choice for this generation;\n      // a later return to it is a new change and asks for its restart.\n      if (!matchesSetup && setupSaved) {\n        setupSettings = undefined\n        setupSaved = false\n      }\n      if (next.mode === resolved.mode\n        && next.port === resolved.port\n        && next.macosMaterial === resolved.macosMaterial\n        && next.linuxMaterial === resolved.linuxMaterial) {\n        if (pending !== undefined) clearImmediate(pending)\n        pending = undefined\n        return\n      }\n      // A native restart prompt here would interrupt the official login that\n      // follows Setup; only a later, different choice asks for its own restart.\n      if (matchesSetup) {\n        if (pending !== undefined) clearImmediate(pending)\n        pending = undefined\n        return\n      }\n      pending ??= setImmediate(() => {\n        pending = undefined\n        void runtime.requestRestart().catch((cause: unknown) => {\n          ctx.logger.error('dsh-plugin-desktop: failed to restart after startup setting change')\n          ctx.logger.error(cause)\n        })\n      })\n    })\n    return () => {\n      stopWatching()\n      if (pending !== undefined) clearImmediate(pending)\n      void lanHttps.stop()\n    }\n  }, 'dsh-plugin-desktop: live browser access and restart-applied native settings')\n  if (runtime.platform !== 'linux') {\n    watchUiThemeSource(ctx, (preference) => { runtime.setThemeSource(preference) })\n  }\n  watchUiLocalePreference(ctx, (preference) => {\n    runtime.setLocalePreference(desktopLocalePreference(preference))\n  })\n  // Cores with the DeepSeek account service (0.1.7+) leave opening the Platform\n  // sign-in page to a native subscriber; older cores never activate this row.\n  ctx.inject(['deepseekAccount'], (accountCtx) => {\n    accountCtx.effect(() => {\n      const account = accountCtx.get('deepseekAccount') as PlatformLoginAccount\n      const lifetime = new AbortController()\n      // A broken watcher only loses the automatic hand-off; the sign-in dialog still offers the link.\n      void watchPlatformLogin(\n        account,\n        (request) => { runtime.platformLogin(request) },\n        () => browserAccess.ordinaryBrowserEnabled,\n        lifetime.signal,\n      ).catch((cause: unknown) => {\n        if (!lifetime.signal.aborted) {\n          accountCtx.logger.error(`dsh-plugin-desktop: platform sign-in watcher stopped: ${cause instanceof Error ? cause.message : String(cause)}`)\n        }\n      })\n      return () => { lifetime.abort() }\n    }, 'dsh-plugin-desktop: platform sign-in hand-off')\n  })\n  ctx.effect(\n    () => {\n      const material = effectiveDesktopWindowMaterial(\n        resolved.mode,\n        runtime.platform,\n        resolved.macosMaterial,\n        resolved.linuxMaterial,\n      )\n      const url = desktopRendererUrl(\n        webServerPort,\n        resolved.mode,\n        runtime.platform,\n        runtime.updates.currentVersion,\n        material,\n      )\n      return runtime.schedule({\n        ...resolved,\n        material,\n        url,\n        authenticationUrl: ctx.connection.authenticatedUrl(new URL(url).origin),\n        rendererAccessHeader: browserAccess.rendererHeader,\n        productName: DESKTOP_PRODUCT_NAME,\n        windowTitle: 'DeepSeek Harness Desktop',\n        iconPath,\n        trayIcons,\n        readLocalePreference: () => {\n          return desktopLocalePreference(readUiLocalePreference(ctx))\n        },\n        readThemeSource: () => readUiThemeSource(ctx),\n        ...(desktopSettings === undefined ? {} : {\n          readRemoteControl: async () => {\n            const aa = desktopSettings.read().aa\n            return aa?.requested === true || aa?.effective === true\n          },\n          enableRemoteControl: async () => {\n            const result = await desktopSettings.selectAa(true)\n            result.afterResponse?.()\n          },\n        }),\n        requestQuit: appExit,\n        requestModeChange: async mode => {\n          const current = settings.get()\n          const storedBrowserCapability = current.openBrowser || current.networkExposure === 'lan'\n          await settings.update(mode !== 'compatibility' && storedBrowserCapability\n            ? { mode, openBrowser: false, networkExposure: 'loopback' }\n            : { mode })\n        },\n        applySetupSettings: async next => {\n          setupSettings = next\n          setupSaved = false\n          try {\n            await settings.update({\n              mode: next.mode,\n              macosMaterial: next.macosMaterial,\n              windowsMaterial: next.windowsMaterial,\n              openBrowser: next.openBrowser,\n              networkExposure: next.networkExposure,\n            })\n          } catch (cause) {\n            setupSettings = undefined\n            throw cause\n          }\n          // The mode is saved; a failed notifications write must not bring back\n          // the native prompt for it.\n          setupSaved = true\n          await ctx.settings.update(DESKTOP_NOTIFICATIONS_SETTINGS_ENTRY_ID, { ...next.notifications })\n        },\n      })\n    },\n    'dsh-plugin-desktop: native shell generation',\n  )\n}\n"
